import{_ as t,o as a,c as o,a8 as s}from"./chunks/framework.DB1tY2mn.js";const f=JSON.parse('{"title":"Untitled string in Mermaid Config Schema","description":"","frontmatter":{"editLink":"https://github.com/mermaid-js/mermaid/edit/develop/packages/mermaid/src/schemas/config.schema.yaml","head":[["link",{"rel":"canonical","href":"https://mermaid.ai/open-source/config/schema-docs/config-defs-usecase-diagram-config-properties-colorscheme.html"}]]},"headers":[],"relativePath":"config/schema-docs/config-defs-usecase-diagram-config-properties-colorscheme.md","filePath":"config/schema-docs/config-defs-usecase-diagram-config-properties-colorscheme.md"}'),i={name:"config/schema-docs/config-defs-usecase-diagram-config-properties-colorscheme.md"};function n(r,e,c,d,l,h){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="untitled-string-in-mermaid-config-schema" tabindex="-1">Untitled string in Mermaid Config Schema <a class="header-anchor" href="#untitled-string-in-mermaid-config-schema" aria-label="Permalink to &quot;Untitled string in Mermaid Config Schema&quot;">​</a></h1><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://mermaid.js.org/schemas/config.schema.json#/$defs/UsecaseDiagramConfig/properties/colorScheme</span></span></code></pre></div><p>How a use case diagram takes its colours from the active theme.</p><p><code>role</code> (the default) gives every element of a kind one colour, read from the <code>usecaseActorBkg</code> / <code>usecaseActorBorder</code>, <code>usecaseBkg</code> / <code>usecaseBorder</code>, and <code>usecaseBoundaryBkg</code> / <code>usecaseBoundaryBorder</code> theme variables. Colour then says what an element <em>is</em>, and it is invariant under insertion, reordering, and renaming -- adding one use case in the middle does not recolour the ones after it, so diffs, documentation screenshots, and visual baselines stay stable.</p><p><code>rotate</code> instead gives each actor, use case, and system boundary its own slot from the theme&#39;s categorical palette (<code>borderColorArray</code> / <code>bkgColorArray</code>), the way ER entities and class boxes are coloured. Actors and use cases share one cycle, and system boundaries run a second one from zero, so a boundary is never forced to match an element inside it. Within the shared cycle the actors are numbered first and the use cases after them, each in declaration order -- an interleaved <code>actor A</code>, <code>usecase U</code>, <code>actor B</code> is therefore numbered A, B, U rather than A, U, B. This buys per-instance variety at the cost of the stability <code>role</code> has: inserting an element shifts the colour of every later element of its own kind, and inserting an actor shifts the use cases too. Only the colour themes (<code>redux-color</code>, <code>redux-dark-color</code>) carry a palette, so on every other theme the two settings render identically.</p><p><code>classDef</code> and <code>style</code> keep overriding both, whichever is set.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Abstract</th><th style="text-align:left;">Extensible</th><th style="text-align:left;">Status</th><th style="text-align:left;">Identifiable</th><th style="text-align:left;">Custom Properties</th><th style="text-align:left;">Additional Properties</th><th style="text-align:left;">Access Restrictions</th><th style="text-align:left;">Defined In</th></tr></thead><tbody><tr><td style="text-align:left;">Can be instantiated</td><td style="text-align:left;">No</td><td style="text-align:left;">Unknown status</td><td style="text-align:left;">Unknown identifiability</td><td style="text-align:left;">Forbidden</td><td style="text-align:left;">Allowed</td><td style="text-align:left;">none</td><td style="text-align:left;"><a href="/dochub/mermaid/schemas/config.schema.json" title="open original schema">config.schema.json*</a></td></tr></tbody></table><h2 id="colorscheme-type" tabindex="-1">colorScheme Type <a class="header-anchor" href="#colorscheme-type" aria-label="Permalink to &quot;colorScheme Type&quot;">​</a></h2><p><code>string</code></p><h2 id="colorscheme-constraints" tabindex="-1">colorScheme Constraints <a class="header-anchor" href="#colorscheme-constraints" aria-label="Permalink to &quot;colorScheme Constraints&quot;">​</a></h2><p><strong>enum</strong>: the value of this property must be equal to one of the following values:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Value</th><th style="text-align:left;">Explanation</th></tr></thead><tbody><tr><td style="text-align:left;"><code>&quot;role&quot;</code></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><code>&quot;rotate&quot;</code></td><td style="text-align:left;"></td></tr></tbody></table><h2 id="colorscheme-default-value" tabindex="-1">colorScheme Default Value <a class="header-anchor" href="#colorscheme-default-value" aria-label="Permalink to &quot;colorScheme Default Value&quot;">​</a></h2><p>The default value is:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;role&quot;</span></span></code></pre></div>',15)])])}const g=t(i,[["render",n]]);export{f as __pageData,g as default};
